using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using static SvdGenerator.Naming;

namespace SvdGenerator
{
    /// <summary>
    /// Turns the device model into the text of the generated headers. Nothing is
    /// written to disk here: the result maps each file name to its content, with
    /// LF line endings whatever the platform.
    /// </summary>
    public static class Emitter
    {
        /// <summary>First characters of every generated file; how the generator recognises its own output.</summary>
        public const string BannerStart = "// Generated by SvdGenerator";

        public static SortedDictionary<string, string> Emit(Device device, string generatorVersion)
        {
            var files = new SortedDictionary<string, string>(StringComparer.Ordinal);
            var banner = Banner(device, generatorVersion);
            var ns = Namespace(device.Name);

            // groupName is optional in CMSIS-SVD. Some vendors (NXP Kinetis,
            // RaspberryPi) leave it empty; fall back to the peripheral's own
            // name so each ungrouped peripheral lives in its own .hpp.
            var groups = device.Peripherals
                .Where(p => p.Base == null)
                .Select(p => (Type: p, Instances: device.Peripherals
                    .Where(i => i == p || i.Base == p)
                    .OrderBy(i => i.Name, StringComparer.Ordinal)
                    .ToList()))
                .GroupBy(t => string.IsNullOrEmpty(t.Type.GroupName) ? t.Type.Name : t.Type.GroupName, StringComparer.Ordinal);

            foreach (var group in groups)
            {
                var sb = new StringBuilder();
                sb.Append(banner);
                AppendLines(sb, "#pragma once", "", "#if __has_include(\"memory.hpp\")", "#include \"memory.hpp\"", "#else", "#include <utility/memory.hpp>", "#endif", "", $"namespace {ns}", "{", "");

                var types = group.ToList();

                // A single type in the group takes the group's name; several
                // (TIM, where some timers have slightly different registers)
                // keep the name of their own peripheral.
                var classNames = types.ToDictionary(
                    t => t.Type,
                    t => PeripheralClass(types.Count == 1 ? group.Key : t.Type.Name));

                foreach (var t in types)
                    sb.Append(PeripheralDefinition(t.Type, classNames[t.Type]));

                foreach (var t in types)
                    foreach (var instance in t.Instances)
                        AppendLines(sb, $"inline {classNames[t.Type]}& {Member(instance.Name)} = *reinterpret_cast<{classNames[t.Type]}*>({Hex(instance.BaseAddress)});");

                AppendLines(sb, "", $"}} // {ns}", "");

                files[UniqueFileName(files, group.Key)] = Normalize(sb);
            }

            files[UniqueFileName(files, "interrupts")] = Normalize(new StringBuilder(banner).Append(Interrupts(device)));
            return files;
        }

        static string UniqueFileName(SortedDictionary<string, string> files, string name)
        {
            // Two groups whose names differ only by case or punctuation would
            // otherwise overwrite each other's header.
            var file = FileName(name);
            for (var n = 2; files.Keys.Contains(file, StringComparer.OrdinalIgnoreCase); n++)
                file = FileName($"{name}_{n}");
            return file;
        }

        static string Normalize(StringBuilder sb) => sb.ToString().Replace("\r\n", "\n");

        static void AppendLines(StringBuilder sb, params string[] lines)
        {
            foreach (var line in lines)
                sb.Append(line).Append('\n');
        }

        static string Banner(Device device, string generatorVersion)
        {
            var sb = new StringBuilder();
            var version = string.IsNullOrEmpty(device.Version) ? string.Empty : $", version {device.Version}";
            AppendLines(sb,
                $"{BannerStart} {generatorVersion}; do not edit.",
                $"// Source: {device.SourceFile} (device {device.Name}{version})",
                $"// SHA-256: {device.SourceSha256}");

            if (device.Notice.Count > 0)
            {
                AppendLines(sb, "//", "// Notice carried by the source file:", "//");
                foreach (var line in device.Notice)
                    AppendLines(sb, line.Length == 0 ? "//" : $"//   {line}");
            }

            AppendLines(sb, "");
            return sb.ToString();
        }

        static string Interrupts(Device device)
        {
            // Dedupe: an SVD can list the same IRQ on every peripheral that
            // shares it (e.g. TIM1_UP_TIM10_IRQn appears on TIM1 and TIM10),
            // and some SVDs even repeat an entry on a single peripheral with
            // slightly different descriptions (FPU). One enumerator per
            // (name, value) is what the C++ enum needs.
            var interrupts = device.Peripherals
                .SelectMany(p => p.Interrupts)
                .GroupBy(i => (i.Name, i.Value))
                .Select(g => g.First())
                .OrderBy(i => i.Value)
                .ThenBy(i => i.Name, StringComparer.Ordinal)
                .ToArray();

            var irqMaxSize = interrupts.Select(i => i.Name.Length).DefaultIfEmpty(0).Max();
            var commentMaxSize = interrupts.Select(i => OneLine(i.Description).Length).DefaultIfEmpty(0).Max();
            var irqCount = interrupts.Select(i => i.Value + 1).DefaultIfEmpty(0).Max();

            var sb = new StringBuilder();

            sb.AppendLine("#pragma once");
            sb.AppendLine();
            sb.AppendLine("#include <cstddef>");

            sb.AppendLine();
            sb.AppendLine($"constexpr std::size_t irq_count = {irqCount};");
            sb.AppendLine();

            sb.AppendLine("enum IRQn_Type");
            sb.AppendLine("{");

            foreach (var interrupt in interrupts)
                sb.AppendLine($"\t{Irq(interrupt.Name).PadRight(irqMaxSize + 10)} = {interrupt.Value,-5}, /** {OneLine(interrupt.Description).PadRight(commentMaxSize)} */");

            sb.AppendLine("};");
            return sb.ToString();
        }

        static string FieldDefinition(Field field, string regClassName)
        {
            var sb = new StringBuilder();
            var className = FieldClass(field.Name);
            var width = field.Width;
            var offset = field.Offset;

            sb.AppendLine($"/**");
            sb.AppendLine($" * {OneLine(field.Description)}");
            sb.AppendLine($" */");
            sb.AppendLine($"class {className} {{");
            sb.AppendLine($"public:");

            sb.AppendLine($"\tstatic constexpr {OffsetType} offset = {offset};");
            sb.AppendLine($"\tstatic constexpr {WidthType} width = {width};");

            if (width != 1)
            {
                sb.AppendLine($"\tstatic constexpr {IntType(width)} range = static_cast<{IntType(width)}>({Ones(width)});");
                sb.AppendLine($"\tstatic constexpr {IntType(width + offset)} mask = static_cast<{IntType(width + offset)}>(static_cast<{ValueType(width + offset)}>(range) << offset);");
            }
            else
            {
                sb.AppendLine($"\tstatic constexpr {IntType(width + offset)} mask = static_cast<{IntType(width + offset)}>(1ULL << offset);");
            }

            sb.AppendLine();
            var rangeCheck = IsExactType(width) ? "" : " & range";
            var defaultValue = width == 1 ? " = true" : "";
            sb.AppendLine($"\tconstexpr {className}({ValueType(width)} value{defaultValue}) : value_(value{rangeCheck}) {{}}");
            sb.AppendLine($"\tconstexpr operator {ValueType(width)}() const {{return value_;}}");

            sb.AppendLine(width == 1
                ? $"\tconstexpr operator {regClassName}() const {{return value_ ? mask : 0;}}"
                : $"\tconstexpr operator {regClassName}() const {{return static_cast<{ValueType(width + offset)}>(static_cast<{ValueType(width + offset)}>(value_) << offset);}}");

            sb.AppendLine($"\tconstexpr operator opsy::utility::clear_set<{regClassName}>() const {{return opsy::utility::clear_set<{regClassName}>(mask, *this);}}");
            sb.AppendLine($"\tconstexpr auto operator|({regClassName} other) const -> {regClassName} {{ return static_cast<{regClassName}>(*this) | other.value_;}}");
            sb.AppendLine($"\tconstexpr auto operator||(opsy::utility::clear_set<{regClassName}> other) const -> opsy::utility::clear_set<{regClassName}> {{return opsy::utility::clear_set<{regClassName}>({regClassName}(mask) | other.clear(), *this | other.set()); }}");

            sb.AppendLine();
            sb.AppendLine("private:");
            sb.AppendLine($"\t {ValueType(width)} value_;");

            sb.AppendLine("};");
            return sb.ToString();
        }

        static string RegisterDefinition(Register register, string className, string description)
        {
            var sb = new StringBuilder();
            var type = ValueType(register.Size);

            sb.AppendLine($"/**");
            sb.AppendLine($" * {OneLine(description)}");
            sb.AppendLine($" */");
            sb.AppendLine($"class {className} {{");
            sb.AppendLine($"public:");

            if (register.Fields.Count > 0)
            {
                foreach (var field in register.Fields)
                {
                    sb.AppendLine();
                    sb.Append(FieldDefinition(field, className));
                }

                sb.AppendLine();

                foreach (var field in register.Fields)
                {
                    var fieldClass = FieldClass(field.Name);
                    if (field.Width == 1)
                        sb.AppendLine($"\t[[nodiscard]] constexpr auto {Member(field.Name)}() const -> {fieldClass} {{return {fieldClass}((value_ & {fieldClass}::mask) != 0);}}");
                    else
                        sb.AppendLine($"\t[[nodiscard]] constexpr auto {Member(field.Name)}() const -> {fieldClass} {{return {fieldClass}(static_cast<{ValueType(field.Width)}>(value_ >> {fieldClass}::offset));}}");
                }
            }

            sb.AppendLine();
            sb.AppendLine($"\tconstexpr {className}({type} value) : value_(value) {{}}");
            sb.AppendLine($"\tconstexpr auto operator |({className} other) const -> {className} {{ return value_ | other.value_; }}");
            sb.AppendLine($"\tconstexpr auto operator ~() const -> {className} {{ return ~value_; }}");
            sb.AppendLine($"\t[[nodiscard]] constexpr auto value() const {{ return value_; }}");

            sb.AppendLine();

            if (register.ResetText != null)
            {
                var reset = Number(register.ResetText, $"register {register.Name}: resetValue");
                sb.AppendLine($"\tstatic constexpr {type} reset_value = {Binary(reset)}; // {reset} {Hex(reset)}");
            }

            sb.AppendLine();
            sb.AppendLine("private:");
            sb.AppendLine($"\t{type} value_;");

            sb.AppendLine("};");
            return sb.ToString();
        }

        static bool IsEquivalent(Field a, Field b) =>
            a.Name == b.Name &&
            a.Width == b.Width &&
            a.Offset == b.Offset &&
            a.DeclaredAccess == b.DeclaredAccess;

        // Two registers share one class when they have the same fields, size and
        // reset value (C0CR, C1CR, ... become cxcr_r).
        static bool IsEquivalent(Register a, Register b) =>
            a.Fields.Count == b.Fields.Count &&
            a.Fields.Count != 0 &&
            b.Fields.All(f => a.Fields.Any(f2 => IsEquivalent(f2, f))) &&
            a.Size == b.Size &&
            a.ResetText == b.ResetText;

        static string PeripheralDefinition(Peripheral peripheral, string className)
        {
            var sb = new StringBuilder();
            var classNames = new Dictionary<Register, string>();
            // Each register's offsetof access path on the peripheral class:
            // either a bare field name, or "_lane_N.field" when the register
            // sits inside a named lane struct.
            var accessPath = new Dictionary<Register, string>();

            sb.AppendLine($"/**");
            sb.AppendLine($" * {OneLine(peripheral.Description)}");
            sb.AppendLine($" */");
            sb.AppendLine($"class {className} {{");
            sb.AppendLine($"public:");

            // The same sorted list feeds register-class equivalence detection,
            // layout walking and the offsetof static_asserts so all three see
            // identical names.
            var registers = peripheral.Registers
                .OrderBy(r => r.Offset)
                .ThenByDescending(r => r.Size)
                .ToList();

            if (registers.Count > 0)
            {
                var families = new List<List<Register>>();
                foreach (var register in registers)
                {
                    var family = families.FirstOrDefault(f => IsEquivalent(f[0], register));
                    if (family != null) family.Add(register);
                    else families.Add(new List<Register> { register });
                }

                var used = new HashSet<string>(StringComparer.Ordinal);
                foreach (var family in families)
                {
                    var names = family.Select(r => RegisterClass(r.Name)).ToList();
                    var name = CommonWithReplace(names, "x");

                    if (name is null)
                        name = names[0];
                    else
                    {
                        // cxcr may already be taken by another family of the
                        // same shape: widen the placeholder until it is free.
                        for (var n = 2; used.Contains(name) && n <= 8; n++)
                            name = CommonWithReplace(names, new string('x', n))!;
                    }

                    var unique = name;
                    for (var n = 2; !used.Add(unique); n++)
                        unique = $"{name}{n}";

                    var description = CommonWithReplace(family.Select(r => r.Description), "X") ?? family[0].Description;

                    sb.AppendLine();
                    sb.Append(RegisterDefinition(family[0], unique, description));

                    foreach (var register in family)
                        classNames.Add(register, unique);
                }

                sb.AppendLine();

                // Walk the registers as a sequence of "footprint groups": each
                // group is a maximal run of registers whose byte spans
                // transitively overlap. Single-register groups lay out flat.
                // Multi-register groups become an anonymous union of lanes
                // (interval coloring). A lane that is a single register at
                // the group's offset rides directly inside the anonymous
                // union (non-POD member is fine in an anonymous union by
                // standard C++); any other lane has to live in a NAMED
                // struct field (`struct { ... } _lane_N;`) because GCC's
                // anonymous-struct extension forbids non-POD members and
                // opsy::utility::memory holds a std::atomic, so it is not
                // POD. Trade-off: byte/half aliases get accessed as
                // `peripheral._lane_N.fooN` instead of `peripheral.fooN`.
                long currentOffset = 0;
                var laneId = 0;

                foreach (var group in BuildFootprintGroups(registers))
                {
                    var groupStart = group[0].Offset;
                    var groupEnd = group.Max(r => r.End);

                    var leadingPadding = groupStart - currentOffset;
                    if (leadingPadding > 0)
                        sb.AppendLine($"\topsy::utility::padding<{leadingPadding}> _p{currentOffset};");

                    var lanes = PartitionLanes(group);

                    if (lanes.Count == 1)
                    {
                        foreach (var r in lanes[0]) accessPath[r] = Member(r.Name);
                        EmitLaneMembers(sb, lanes[0], groupStart, classNames, "\t");
                    }
                    else
                    {
                        sb.AppendLine("\tunion {");
                        foreach (var lane in lanes)
                        {
                            var bare = lane.Count == 1 && lane[0].Offset == groupStart;
                            if (bare)
                            {
                                accessPath[lane[0]] = Member(lane[0].Name);
                                EmitLaneMembers(sb, lane, groupStart, classNames, "\t\t");
                            }
                            else
                            {
                                var laneName = $"_lane_{laneId++}";
                                foreach (var r in lane) accessPath[r] = $"{laneName}.{Member(r.Name)}";
                                sb.AppendLine("\t\tstruct {");
                                EmitLaneMembers(sb, lane, groupStart, classNames, "\t\t\t");
                                sb.AppendLine($"\t\t}} {laneName};");
                            }
                        }
                        sb.AppendLine("\t};");
                    }

                    currentOffset = groupEnd;
                }
            }

            sb.AppendLine("};");

            if (registers.Count > 0)
            {
                sb.AppendLine();
                sb.AppendLine($"static_assert(std::is_standard_layout_v<{className}>);");
                foreach (var register in registers)
                    sb.AppendLine($"static_assert(offsetof({className}, {accessPath[register]}) == {register.Offset});");
            }

            sb.AppendLine();
            return sb.ToString();
        }

        // Build maximal runs of registers whose byte spans transitively overlap.
        // Input: registers sorted by offset asc, then size desc.
        // Output: groups in offset-asc order; within a group, the same sort.
        static List<List<Register>> BuildFootprintGroups(List<Register> sorted)
        {
            var groups = new List<List<Register>>();
            long currentEnd = -1;
            foreach (var r in sorted)
            {
                if (groups.Count == 0 || r.Offset >= currentEnd)
                {
                    groups.Add(new List<Register> { r });
                    currentEnd = r.End;
                }
                else
                {
                    groups[^1].Add(r);
                    if (r.End > currentEnd) currentEnd = r.End;
                }
            }
            return groups;
        }

        // Greedy interval coloring on a single footprint group. With the input
        // sorted (offset asc, size desc) the largest register lands in lane 0,
        // halfword aliases collapse into lane 1, byte aliases into lane 2.
        static List<List<Register>> PartitionLanes(List<Register> group)
        {
            var lanes = new List<List<Register>>();
            var laneEnds = new List<long>();
            foreach (var r in group)
            {
                var idx = -1;
                for (var i = 0; i < laneEnds.Count; i++)
                {
                    if (laneEnds[i] <= r.Offset) { idx = i; break; }
                }
                if (idx == -1)
                {
                    idx = lanes.Count;
                    lanes.Add(new List<Register>());
                    laneEnds.Add(0);
                }
                lanes[idx].Add(r);
                laneEnds[idx] = r.End;
            }
            return lanes;
        }

        // Emit a sequence of registers belonging to one lane, inserting padding
        // for any internal gap between consecutive registers. Padding is named
        // by the byte offset where it starts; intra-lane paddings are scoped to
        // the lane's named struct so two lanes with padding at the same offset
        // do not collide at peripheral scope.
        static void EmitLaneMembers(
            StringBuilder sb, List<Register> lane, long laneStart,
            Dictionary<Register, string> classNames, string indent)
        {
            var cursor = laneStart;
            foreach (var r in lane)
            {
                if (r.Offset > cursor)
                    sb.AppendLine($"{indent}opsy::utility::padding<{r.Offset - cursor}> _p{cursor};");

                var template = r.Access switch
                {
                    Access.ReadOnly => "opsy::utility::read_only_memory",
                    Access.WriteOnly => "opsy::utility::write_only_memory",
                    _ => "opsy::utility::memory",
                };
                sb.AppendLine($"{indent}{template}<{ValueType(r.Size)},{classNames[r]}> {Member(r.Name)};");

                cursor = r.End;
            }
        }
    }
}
